    def put(self, key, value, ttl):
        with self.lock:
            self._purge()
            created = key not in self.entries
            expires = None if ttl is None else time.time() + ttl
            self.entries[key] = {"value": value, "expires_at": expires}
            self._save()
            return created

    def get(self, key):
        with self.lock:
            changed = self._purge()
            if changed:
                self._save()
            item = self.entries.get(key)
            return None if item is None else item["value"]

    def delete(self, key):
        with self.lock:
            self._purge()
            if key not in self.entries:
                return False
            del self.entries[key]
            self._save()
            return True

    def keys(self):
        with self.lock:
            if self._purge():
                self._save()
            return sorted(self.entries)


class Handler(BaseHTTPRequestHandler):
    server_version = "PersistentKV/1.0"

    def log_message(self, fmt, *args):
        print("%s - %s" % (self.address_string(), fmt % args), file=sys.stderr)

    def send_json(self, status, payload=None):
        data = b"" if payload is None else json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode()
        self.send_response(status)
        if payload is not None:
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
        else:
            self.send_header("Content-Length", "0")
        self.end_headers()
        if data:
            self.wfile.write(data)

    def error(self, status, message):
        self.send_json(status, {"error": message})

    def key_from_path(self, path):
        prefix = "/v1/kv/"
        if not path.startswith(prefix):
            return None
        encoded = path[len(prefix):]
        if not encoded or "/" in encoded:
            return None
        try:
            key = unquote(encoded, encoding="utf-8", errors="strict")
            key.encode("utf-8")
        except (UnicodeDecodeError, UnicodeEncodeError):
            return None
        return key if key else None

    def read_body(self):
        raw_length = self.headers.get("Content-Length")
        try:
            length = int(raw_length) if raw_length is not None else 0
        except ValueError:
            raise ValueError("invalid Content-Length")
        if length < 0 or length > MAX_BODY:
            raise OverflowError
        return self.rfile.read(length)

    def do_GET(self):
        path = self.path.split("?", 1)[0]
        if path == "/health":
            return self.send_json(200, {"status": "ok"})
        if path == "/v1/keys":
            return self.send_json(200, {"keys": self.server.store.keys()})
        key = self.key_from_path(path)
        if key is None:
            return self.error(404, "not found")
        value = self.server.store.get(key)
        if value is None and not self.server.store.has(key):
            return self.error(404, "key not found")
        self.send_json(200, {"key": key, "value": value})

    def do_DELETE(self):
        key = self.key_from_path(self.path.split("?", 1)[0])
        if key is None:
            return self.error(404, "not found")
        if self.server.store.delete(key):
            self.send_json(204)
        else:
            self.error(404, "key not found")

    def do_PUT(self):
        key = self.key_from_path(self.path.split("?", 1)[0])
        if key is None:
            return self.error(404, "not found")
        try:
            body = self.read_body()
        except OverflowError:
            return self.error(413, "request body too large")
        except ValueError as exc:
            return self.error(400, str(exc))
        try:
            obj = json.loads(body)
        except (json.JSONDecodeError, UnicodeDecodeError):
            return self.error(400, "malformed JSON")
        if not isinstance(obj, dict) or "value" not in obj or set(obj) - {"value", "ttl_seconds"}:
            return self.error(400, "body must contain value and optional ttl_seconds")
        ttl = obj.get("ttl_seconds")
        if ttl is not None and (isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or not math.isfinite(ttl) or ttl <= 0):
            return self.error(400, "ttl_seconds must be finite and greater than zero")
        try:
            created = self.server.store.put(key, obj["value"], ttl)
        except (OSError, TypeError, ValueError) as exc:
            print(f"save failed: {exc}", file=sys.stderr)
            return self.error(500, "could not persist value")
        self.send_json(201 if created else 200, {"key": key, "value": obj["value"]})

    def do_POST(self):
        self.error(405, "method not allowed")

    def do_HEAD(self):
        self.error(405, "method not allowed")


class KVServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address, store):
        super().__init__(address, Handler)
        self.store = store


def main():
    parser = argparse.ArgumentParser(description="Persistent HTTP key-value service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, required=True)
    parser.add_argument("--data", required=True)
    args = parser.parse_args()
    server = KVServer((args.host, args.port), Store(args.data))
    def stop(signum, frame):
        threading.Thread(target=server.shutdown, daemon=True).start()
    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    print(f"LISTENING {server.server_address[1]}", flush=True)
    try:
        server.serve_forever()
    finally:
        server.server_close()

if __name__ == "__main__":
