#!/usr/bin/env python3
"""Persistent dependency-free HTTP key-value service."""

from __future__ import annotations

import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote

MAX_BODY = 1024 * 1024


class Store:
    def __init__(self, path: str):
        self.path = os.path.abspath(path)
        self.lock = threading.RLock()
        self.entries: dict[str, dict] = {}
        self._load()

    def _load(self):
        try:
            with open(self.path, encoding="utf-8") as f:
                raw = json.load(f)
            if not isinstance(raw, dict):
                raise ValueError("store must be an object")
            now = time.time()
            for key, item in raw.items():
                if isinstance(key, str) and isinstance(item, dict) and "value" in item:
                    expires = item.get("expires_at")
                    if expires is None or (isinstance(expires, (int, float)) and expires > now):
                        self.entries[key] = {"value": item["value"], "expires_at": expires}
        except FileNotFoundError:
            return
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            print(f"failed to load data file: {exc}", file=sys.stderr)

    def _purge(self, now=None):
        now = time.time() if now is None else now
        expired = [k for k, item in self.entries.items()
                   if item["expires_at"] is not None and item["expires_at"] <= now]
        for key in expired:
            del self.entries[key]
        return bool(expired)

    def _save(self):
        directory = os.path.dirname(self.path) or "."
        fd, temporary = tempfile.mkstemp(prefix=".kv-", suffix=".tmp", dir=directory)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(self.entries, f, ensure_ascii=False, separators=(",", ":"))
                f.flush()
                os.fsync(f.fileno())
            os.replace(temporary, self.path)
        finally:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass

    def put(self, key, value, ttl=None):
        with self.lock:
            self._purge()
            existed = key in self.entries
            self.entries[key] = {"value": value, "expires_at": None if ttl is None else time.time() + ttl}
            self._save()
            return existed

    def get(self, key):
        with self.lock:
            changed = self._purge()
            if changed:
                self._save()
            return self.entries.get(key)

    def delete(self, key):
        with self.lock:
            self._purge()
            if key not in self.entries:
                return False
            del self.entries[key]
            self._save()
            return True

    def keys(self):
        with self.lock:
            if self._purge():
                self._save()
            return sorted(self.entries)


def json_bytes(obj):
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")


class Handler(BaseHTTPRequestHandler):
    server_version = "PersistentKV/1.0"

    def send_json(self, status, obj=None):
        body = b"" if obj is None else json_bytes(obj)
        self.send_response(status)
        if obj is not None:
            self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def error(self, status, message):
        self.send_json(status, {"error": message})

    def read_json(self):
        length = self.headers.get("Content-Length")
        try:
            size = int(length) if length is not None else 0
        except ValueError:
            raise ValueError("invalid Content-Length")
        if size < 0 or size > MAX_BODY:
            raise OverflowError
        raw = self.rfile.read(size)
        if len(raw) != size:
            raise ValueError("incomplete request body")
        try:
            return json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            raise ValueError("malformed JSON")

